// Pure producer ports; safe to run in a module worker. Keep the hashing types,
// truncation and LCG offset step identical to the Solidity producers.
import { AbiCoder, keccak256, toBeHex } from '../vendor/ethers-app.mjs';
const coder = AbiCoder.defaultAbiCoder();
const LCG_MULT = 6364136223846793005n;
const FOIL_SEED_TAG = keccak256(new TextEncoder().encode('foil-seed'));
const GOLD_SIX_REPLACEMENT_TAG = keccak256(new TextEncoder().encode('GOLD_SIX_REPLACEMENT_V1'));
const GOLD_SIX_TAKEN = 1n << 255n;
export function ticketStreamReplay(key) {
  key = BigInt(key);
  const domain = Number((key >> 248n) & 0x7fn);
  if (domain < 0x20 || domain > 0x23) return null;
  return { foil: domain === 0x23, offset: Number(key & 0xffffffffn),
    identity: key & ~(GOLD_SIX_TAKEN | 0xffffffffn), goldSixTaken: Boolean(key & GOLD_SIX_TAKEN) };
}
export function decodeBaseKey(key) {
  key = BigInt(key);
  return { level: Number((key >> 224n) & 0xffffffn), queueIdx: Number((key >> 192n) & 0xffffffffn),
    player: toBeHex((key >> 32n) & ((1n << 160n) - 1n), 20), owed: Number(key & 0xffffffffn) };
}
export const isFoil = (key, take) => ticketStreamReplay(key)?.foil
  ?? ((BigInt(key) & 0xffffffffn) === 0n && Number(take) === 16);
export function deriveTraits(baseKey, startIndex, count, entropy, replayState = null) {
  const stream = ticketStreamReplay(baseKey);
  if (stream) {
    baseKey = stream.identity;
    replayState ??= { goldSixTaken: stream.goldSixTaken };
  }
  const result = new Uint8Array(count); const end = startIndex + count;
  for (let i = startIndex; i < end;) {
    const seed = BigInt(keccak256(coder.encode(['uint256', 'uint256', 'uint32'], [baseKey, entropy, Math.floor(i / 16)])));
    let s = BigInt.asUintN(64, seed) | 1n; const offset = i & 15;
    s = BigInt.asUintN(64, s * (LCG_MULT + BigInt(offset)) + BigInt(offset));
    for (let j = offset; j < 16 && i < end; j++, i++) {
      s = BigInt.asUintN(64, s * LCG_MULT + 1n);
      const rnd = Number(((s & 0xffffffffn) * 256n) >> 32n);
      const found = [64, 128, 192, 224, 240, 248, 254].findIndex(cut => rnd < cut);
      let trait = ((found < 0 ? 7 : found) << 3) | Number((s >> 32n) & 7n) | ((i & 3) << 6);
      if (stream && trait === 253) {
        if (replayState.goldSixTaken) {
          const symbol = Number(BigInt(keccak256(coder.encode(['uint256', 'bytes32'], [s, GOLD_SIX_REPLACEMENT_TAG]))) % 7n);
          trait = 248 + symbol + (symbol >= 5 ? 1 : 0);
        } else replayState.goldSixTaken = true;
      }
      result[i - startIndex] = trait;
    }
  }
  return result;
}
export function foilCuts(multBps) {
  const boost = Number(multBps) - 10000;
  const weights = [32 * 60, Math.floor(16 * 60 * (50000 + boost * 2) / 50000), Math.floor(8 * 60 * (50000 + boost * 3) / 50000),
    Math.floor(6 * 60 * (50000 + boost * 4) / 50000), Math.floor(2 * 60 * (50000 + boost * 5) / 50000)];
  const remaining = 15360 - weights.reduce((a, b) => a + b, 0); const common = Math.floor(remaining / 3);
  let cumulative = 0;
  return [common + remaining % 3, common, common, ...weights].slice(0, 7).map(weight => cumulative += weight);
}
export function deriveFoil({ buyer, level, entropy, multBps }) {
  const cut = foilCuts(multBps);
  return Array.from({ length: 4 }, (_, i) => {
    const seed = BigInt(keccak256(coder.encode(['uint256', 'address', 'uint24', 'bytes32', 'uint256'], [entropy, buyer, level, FOIL_SEED_TAG, i])));
    return Array.from({ length: 4 }, (_, q) => {
      const s = seed >> BigInt(q * 64); const scaled = Number(((s & 0xffffffffn) * 15360n) >> 32n);
      const found = cut.findIndex(c => scaled < c);
      return ((found < 0 ? 7 : found) << 3) | Number((s >> 32n) & 7n) | (q << 6);
    });
  });
}

export function decodeEntryReveal(log, level, player) {
  const target = toBeHex((BigInt(level) << 160n) | BigInt(player), 32).toLowerCase();
  if (log.topics?.length !== 4 || !/^0x[0-9a-f]{64}$/i.test(log.data)) throw new Error('Invalid EntryTraitsRevealed encoding.');
  const packed = BigInt(log.data); if (packed >> 144n) throw new Error('Unexpected reveal payload bits.');
  const entries = [];
  for (let seat = 0; seat < 4; seat++) {
    if (log.topics[seat].toLowerCase() !== target) continue;
    for (let q = 0; q < 4; q++) {
      const lane = seat * 4 + q;
      if (!(packed & (1n << BigInt(128 + lane)))) continue;
      const trait = Number((packed >> BigInt(lane * 8)) & 255n);
      if ((trait >> 6) !== q) throw new Error('Reveal quadrant mismatch.');
      entries.push(trait);
    }
  }
  return entries;
}
